 let syncIntent=false,publishTarget=null,preferenceDraft=null,proposalMember=null,proposalDay=0;
 let current=null,activeId=null,busy=false,error='',lastSync=0,day=0,invitation=null,polling=false,dirty=false;
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(saved))}catch{ui.toast('浏览器无法保存房间入口，请保留邀请链接。')}};
