 function hub(){syncIntent=false;sessionStorage.removeItem('nextstop-sync-plan');activeId=null;rememberRoom(null);current=null;error='';ui.close();ui.navigate('room')}
 function entry(join=null){invitation=join;let draft={};try{draft=JSON.parse(sessionStorage.getItem('nextstop-room-draft')||'{}')}catch{}ui.sheet(join?'加入这次旅行':'创建旅行房间',`<p>${join?'填写你在小分队里的昵称，加入后一起选城市、看行程。':'先给小分队起个名字，再把邀请链接发给朋友。最多 12 人一起选。'}</p>${join?'':`<label class="field"><span>房间名称</span><input id="room-title" maxlength="40" value="${esc(draft.title||'我们的下一站')}"></label>`}<label class="field"><span>你的昵称</span><input id="room-name" maxlength="20" value="${esc(draft.name||'')}" placeholder="朋友怎么称呼你？" autocomplete="nickname"></label><p class="small-note">无需注册或登录，填写昵称就能${join?'加入':'创建'}房间。</p><p class="small-note">身份保存在当前浏览器。请使用同一浏览器继续；清除浏览器数据或换设备后，需通过邀请重新加入，发起人身份不会自动恢复。</p><p class="form-error" id="room-error" role="alert"></p>`,`<button class="primary" data-room-action="${join?'join':'create'}">${join?'加入房间':syncIntent?'创建房间并继续同步':'创建并邀请朋友'}</button>`)}
 async function enter(join){if(busy)return;const name=$('#room-name').value.trim(),title=$('#room-title')?.value.trim();if(!name||(!join&&!title)){$('#room-error').textContent='请先填写昵称和房间名称。';return}try{sessionStorage.setItem('nextstop-room-draft',JSON.stringify({name,title}))}catch{}busy=true;const button=$('[data-room-action="'+(join?'join':'create')+'"]');button.disabled=true;button.textContent='正在连接房间…';const prior=join&&saved[join.id],token=prior?.token||random();try{const data=await api(join?'/'+join.id+'/join':'',join?{name,invite:join.secret}:{name,title},token),id=data.room.id;saved[id]={token,title:data.room.title,invite:data.invite||prior?.invite||'',name};save();activeId=id;rememberRoom(id);current=null;accept(data,id);history.replaceState(null,'',location.pathname+location.search);ui.close();ui.navigate('room');if(syncIntent&&ui.activePlan()){busy=false;await preparePublish(id)}else if(!join)inviteSheet()}catch(e){$('#room-error').textContent=e.message;button.disabled=false;button.textContent=join?'加入房间':syncIntent?'创建房间并继续同步':'创建并邀请朋友'}finally{busy=false}}
 async function open(id){if(!saved[id])return;activeId=id;rememberRoom(id);current=null;error='';day=0;ui.close();ui.navigate('room');await refresh()}
