  return `<article class="room-member-card ${mine?'is-me':''}"><div class="member-stamp-frame">${roomPhoto(first?.name,'member-photo')}<i class="member-stamp-notch-left" aria-hidden="true"></i><i class="member-stamp-notch-right" aria-hidden="true"></i><span class="member-stamp-serial" aria-hidden="true">NEXT STOP · ${String(index+1).padStart(2,'0')}</span><span class="member-postmark" aria-hidden="true"><svg class="member-cancel-waves" viewBox="0 0 41 30"><path d="M0 4c7-5 13 5 20 0s14 5 21 0M0 14c7-5 13 5 20 0s14 5 21 0M0 24c7-5 13 5 20 0s14 5 21 0"/></svg><b>下一站</b><strong>${esc(postmark)}</strong><small>旅伴想法</small></span></div><div class="member-stamp-details"><div class="member-stamp-city"><h3>${esc(city)}</h3><span>${esc(days)}</span></div><p class="member-stamp-budget">${esc(budget)}</p>${wants.length>1?`<div class="member-more"><span>还想去</span>${wants.slice(1).map(c=>r.candidates.some(x=>x.id===c.id)?`<button data-room-action="city-detail" data-id="${esc(c.id)}">${esc(c.name)}</button>`:`<span>${esc(c.name)}</span>`).join('')}</div>`:''}</div><header><span class="member-initial" aria-hidden="true">${esc(Array.from(m.name)[0]||'旅')}</span><strong>${esc(m.name)}${mine?' · 我':''}</strong><small>${m.id===r.owner?'房间发起人':'同行伙伴'}</small></header><footer class="member-ticket-footer"><span>${p.dislikes?.length?'这次不想去 '+p.dislikes.map(c=>esc(c.name)).join('、'):'暂无排除的城市'}</span>${mine&&!r.closed?'<button class="member-edit" data-room-action="edit-preferences">编辑想法</button>':''}</footer></article>`;
