 function roomPlanEntries(r){return [...(r.plan?[{plan:r.plan,city:r.candidates.find(c=>c.id===r.plan.city)||{name:ui.cities().find(c=>c.id===r.plan.city)?.name||r.plan.city},id:'',version:r.planVersion}]:[]),...Object.entries(r.proposals||{}).map(([id,x])=>({...x,id}))]}
 function roomWants(r){const cities=new Map();for(const m of r.members)for(const c of m.preferences?.wants||[]){const key=c.name.replace(/市$/,'');if(!cities.has(key))cities.set(key,{...c,names:[]});cities.get(key).names.push(m.name)}return [...cities.values()]}
 function updateRoomSection(){
  const main=$('#main'),ideas=$('#room-ideas');if(!main||!ideas)return;
  const active=ideas.getBoundingClientRect().top<=main.getBoundingClientRect().top+130?'ideas':'plans';
  document.querySelectorAll('.room-panel-nav [data-value]').forEach(link=>{if(link.dataset.value===active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')});
 }
 document.addEventListener('scroll',e=>{if(e.target===$('#main'))updateRoomSection()},{capture:true,passive:true});
 function roomWorkspace(r){
  requestAnimationFrame(updateRoomSection);
  const entries=roomPlanEntries(r),wants=roomWants(r),chosen=r.members.filter(m=>m.preferences?.wants?.length).length;
  const hero=`<header class="room-travel-hero"><div><h1>一起出发，<br>把旅行<span>定下来。</span></h1>${!r.closed?`<button class="primary" data-room-action="choose-plan-city">生成我的方案 ${ui.icon('arrow-right')}</button>`:''}</div><div class="room-overview-map map-panel" id="room-overview-map" aria-label="房间旅行愿望地图，可拖动和缩放"><svg role="img" aria-label="标出同行伙伴想去城市的中国地图"></svg><div class="room-map-top"><strong>大家想去的地方</strong><span>${wants.length} 座城市 · ${chosen} 位伙伴已选</span></div><div class="map-controls" role="group" aria-label="房间地图缩放"><button data-room-map-zoom="in" aria-label="放大房间地图">${ui.icon('plus')}</button><span class="zoom-level">1.0×</span><button data-room-map-zoom="out" aria-label="缩小房间地图">${ui.icon('minus')}</button><button data-room-map-zoom="reset" aria-label="重置房间地图">${ui.icon('scan')}</button></div><span class="map-gesture-hint">拖动查看 · 滚轮放大</span>${!wants.length?'<div class="room-map-empty">伙伴还没标注想去的地方</div>':''}</div></header>`;
  const ideaStrip=`<section class="room-overview-bar"><div><strong>我们想去的地方</strong><small>${chosen} 位已选 · ${r.members.length-chosen} 位待选</small></div><div class="room-want-summary">${wants.map(c=>`<div><strong>${esc(c.name)}</strong><small>${c.names.map(esc).join('、')}</small></div>`).join('')||'<span>还没有选择城市，可以先编辑自己的想法。</span>'}</div></section>`;
  const strip=`<section class="room-overview-bar"><div><strong>${esc(r.title)}</strong><small>${r.members.length} 位同行伙伴</small></div><div><strong>${entries.length} 份方案</strong><small>一起查看和讨论</small></div>${!r.closed?'<button class="secondary" data-action="plan-library">选择已保存的行程</button>':''}</section>`;
  return `<div class="room-design"><aside class="room-design-rail"><button class="text-button room-back" data-room-action="hub">${ui.icon('arrow-left')}我的房间</button><h2>${esc(r.title)}</h2><p>${r.members.length} 位同行伙伴<br>你是${esc(r.members.find(m=>m.id===r.me)?.name||'同行伙伴')}${isOwner()?' · 房间发起人':''}</p><nav class="room-panel-nav" aria-label="旅行房间导航"><a href="#room-plans" data-room-action="room-panel" data-value="plans" aria-current="location">${ui.icon('notebook-tabs')}旅行方案<span>${entries.length}</span></a><a href="#room-ideas" data-room-action="room-panel" data-value="ideas">${ui.icon('users-round')}旅伴想法<span>${r.members.length}</span></a></nav><div class="room-rail-people"><strong>同行伙伴</strong><div>${r.members.map(m=>`<span title="${esc(m.name)}">${esc(Array.from(m.name)[0]||'旅')}</span>`).join('')}</div></div>${isOwner()&&!r.closed?'<button class="secondary room-invite" data-room-action="invite">邀请朋友</button>':''}<div class="room-rail-bottom"><img src="assets/anan-siamese-travel.png" alt="安安"><div><strong>安安在这里</strong><small>一起把旅行安排好</small></div></div><button class="text-button room-settings" data-room-action="settings">${ui.icon('settings')}房间设置</button></aside><div class="room-design-content">${error||r.closed?`<p class="room-sync ${error?'has-error':''}" role="status">${esc(error||'房间已关闭 · 保留只读内容')}</p>`:''}${hero}${strip}${roomTools.overview(r)}<section id="room-plans" class="room-section room-plan-entry" aria-label="旅行方案"><div class="room-section-heading"><h2>旅行方案 <small>${entries.length} 份</small></h2><button class="text-button" data-room-action="refresh">${ui.icon('refresh-cw')}刷新同步</button></div>${proposalList(r)}${!entries.length?'<p class="room-empty">还没有方案。从这里生成行程，完成后会自动放进房间。</p>':''}<p class="small-note">房间里的伙伴都可以查看、共同编辑和投票。</p></section><section id="room-ideas" class="room-section room-preferences" aria-label="旅伴想法"><div class="room-section-heading"><h2>同行伙伴的旅行想法</h2>${!r.closed?'<button class="text-button" data-room-action="edit-preferences">编辑我的想法</button>':''}</div>${ideaStrip}<div class="room-member-grid">${r.members.map((m,i)=>memberCard(m,r,i)).join('')}</div></section>${candidateSection(r)}</div></div>`;
 }

 function cityCard(c,r,index){
  const votes=r.votes[c.id]||{},supporters=r.members.filter(m=>votes[m.id]==='最想去'),disagree=Object.values(votes).includes('这次不考虑'),image=window.CITY_HIGHLIGHTS?.[c.name.replace(/市$/,'')]?.items?.[0]?.src;
  return `<button class="room-city-tile" data-room-action="city-detail" data-id="${esc(c.id)}" aria-label="查看${esc(c.name)}的同行意愿，${supporters.length} 人最想去${disagree?'，有不同意见':''}"><span class="room-city-cover">${image?`<img src="${esc(image)}" alt="" loading="lazy">`:`<span class="room-city-placeholder">${ui.icon('map-pin')}</span>`}<span class="room-city-index">${String(index+1).padStart(2,'0')} / ${String(r.candidates.length).padStart(2,'0')}</span><span class="room-city-location"><strong>${esc(c.name)}</strong><small>${esc(c.province||'一起去看看')}</small></span></span><span class="room-city-footer"><span class="room-city-vote">${supporters.length?`<span class="room-city-voters" aria-hidden="true">${supporters.slice(0,3).map((m,i)=>`<i title="${esc(m.name)}" class="${i%2?'cool':''}">${esc(Array.from(m.name)[0]||'旅')}</i>`).join('')}${supporters.length>3?`<i class="more">+${supporters.length-3}</i>`:''}</span>`:''}<span class="room-city-vote-copy"><strong>${supporters.length?`${supporters.length} 人想去`:'还没人表态'}</strong>${disagree?'<small>有不同意见</small>':''}</span></span><span class="room-city-arrow" aria-hidden="true">${ui.icon('arrow-up-right')}</span></span></button>`
 }
 function cityDetail(id){
  const r=current,index=current.candidates.findIndex(c=>c.id===id);if(index<0)return;
  const c=r.candidates[index],votes=r.votes[id]||{},photo=window.CITY_HIGHLIGHTS?.[c.name.replace(/市$/,'')]?.items?.[0]?.src;
  const groups=[{value:'最想去',note:'这趟最期待这里',className:'wish'},{value:'可以接受',note:'去这里也很开心',className:'okay'},{value:'这次不考虑',note:'想先看看别处',className:'pass'}];
  const pending=r.members.filter(m=>!votes[m.id]),name=m=>esc(Array.from(m.name)[0]||'旅');
  const person=m=>`<span class="ballot-person"><i aria-hidden="true">${name(m)}</i>${esc(m.name)}${m.id===r.me?' · 我':''}</span>`;
  const previous=r.candidates[(index-1+r.candidates.length)%r.candidates.length],next=r.candidates[(index+1)%r.candidates.length];
  ui.sheet(c.name+' · 大家怎么想',`<div class="ballot-page"><header class="ballot-top"><div><span class="ballot-kicker">NEXT STOP / CITY BALLOT ${String(index+1).padStart(2,'0')}</span><h3>${esc(c.name)}这一站，走不走？</h3></div></header><section class="ballot-ticket" aria-label="${esc(c.name)}目的地票"><div class="ballot-ticket-photo">${photo?`<img src="${esc(photo)}" alt="${esc(c.name)}城市风景">`:''}<div class="ballot-ticket-copy"><small>目的地候选 · ${esc(c.province||'下一站')}</small><strong>${esc(c.name)}</strong><span>${esc(r.title)} / ${r.members.length} 位同行伙伴</span></div><nav class="ballot-city-nav" aria-label="切换候选城市"><button data-room-action="city-shift" data-value="-1" aria-label="上一个候选城市：${esc(previous.name)}" title="${esc(previous.name)}" ${r.candidates.length<2?"disabled":""}>${ui.icon("arrow-left")}<span><small>上一站</small><b>${esc(previous.name)}</b></span></button><span class="ballot-city-counter"><small>地点</small><strong>${String(index+1).padStart(2,"0")}</strong><em>/ ${String(r.candidates.length).padStart(2,"0")}</em></span><button data-room-action="city-shift" data-value="1" aria-label="下一个候选城市：${esc(next.name)}" title="${esc(next.name)}" ${r.candidates.length<2?"disabled":""}><span><small>下一站</small><b>${esc(next.name)}</b></span>${ui.icon("arrow-right")}</button></nav></div><div class="ballot-ticket-stub"><small>ROOM VOTE</small><div><strong>${r.members.length-pending.length} / ${r.members.length}</strong><span>位伙伴已表态</span></div><i class="ballot-barcode" aria-hidden="true"></i></div></section><div class="ballot-main"><section class="ballot-board"><header><h4>大家的选择</h4><span>每人一票 · 房间同步</span></header><div class="ballot-lanes">${groups.map(g=>{const members=r.members.filter(m=>votes[m.id]===g.value);return `<div class="ballot-lane ${g.className}"><strong>${String(members.length).padStart(2,'0')}</strong><b>${g.value}</b><small>${g.note}</small><div class="ballot-people">${members.length?members.map(person).join(''):'<span class="ballot-no-votes">还没有伙伴选择</span>'}</div></div>`}).join('')}</div><p class="ballot-pending">${pending.length?`${pending.map(m=>`<i title="${esc(m.name)}">${name(m)}</i>`).join('')}<span>${pending.map(m=>esc(m.name)).join('、')}还没表态</span>`:'大家都已表态'}</p></section><section class="ballot-mine"><h4>我的选票</h4><div class="ballot-choices">${groups.map(g=>`<button class="ballot-choice ${votes[r.me]===g.value?'selected':''}" data-room-action="vote" data-id="${esc(id)}" data-value="${g.value}" aria-pressed="${votes[r.me]===g.value}" ${r.closed?'disabled':''}><i aria-hidden="true"></i><span>${g.value}</span>${votes[r.me]===g.value?'<small>当前选择 ✓</small>':''}</button>`).join('')}</div><p>${r.closed?'房间已关闭，投票仅供查看。':'点击即可改签；伙伴会看到更新。'}</p></section></div><p id="room-error" class="form-error" role="alert"></p></div>`,`${r.plan?'<button class="secondary" data-room-action="view-plan">查看共享行程 ↗</button>':''}${!r.closed&&(isOwner()||c.addedBy===r.me)?`<button class="text-button" data-room-action="remove-city" data-id="${esc(id)}">移出候选</button>`:''}${!r.closed?`<button class="primary" data-room-action="plan-city" data-id="${esc(id)}">让安安推荐${esc(c.name)}的玩法 ↗</button>`:''}`);
  $('#sheet').classList.add('vote-ticket-sheet');
 }
 function capturePreferences(){if(!preferenceDraft||!$('#pref-budget'))return;preferenceDraft.budget=$('#pref-budget').value;preferenceDraft.min=$('#pref-days-min').value;preferenceDraft.max=$('#pref-days-max').value;preferenceDraft.queries={wants:$('#pref-wants-query').value,dislikes:$('#pref-dislikes-query').value}}
 function addPreferenceInput(d,key){
  const name=(d.queries?.[key]||'').trim();
  if(name.length<2||name.length>30||!/^\p{L}[\p{L}\p{N}\s·•.（）()\-]*$/u.test(name))throw Error('请填写有效城市名称，至少两个字。');
  const normalize=x=>x.replace(/市$/,'');
  const c=ui.cities().find(c=>normalize(c.name)===normalize(name))||current.candidates.find(c=>normalize(c.name)===normalize(name))||{id:'custom-'+crypto.randomUUID(),name,province:''};
  const other=key==='wants'?'dislikes':'wants';
  if(d[other].some(x=>normalize(x.name)===normalize(c.name)))throw Error('这个城市已在另一类里，请先移除后再添加。');
  if(!d[key].some(x=>normalize(x.name)===normalize(c.name))){
   if(d[key].length>=30)throw Error('每类最多添加 30 座城市。');
   d[key].push({id:c.id,name:c.name,province:c.province||''});
  }
  d.queries[key]='';
 }
 function editPreferences(fresh=true){
  if(fresh){const p=current.members.find(m=>m.id===current.me)?.preferences||{};preferenceDraft={budget:p.budget??'',min:p.days?.min??'',max:p.days?.max??'',wants:JSON.parse(JSON.stringify(p.wants||[])),dislikes:JSON.parse(JSON.stringify(p.dislikes||[])),queries:{wants:'',dislikes:''}}}
  const p=preferenceDraft,me=current.members.find(m=>m.id===current.me);
  const citySection=key=>`<section class="pref-city-card ${key}"><div class="pref-city-head"><span class="pref-city-symbol">${ui.icon(key==='wants'?'heart':'ban')}</span><div><h3>${key==='wants'?'想去的城市':'这次不想去的城市'}</h3><p>${key==='wants'?'把想去的地方收进旅行愿望册':'先划掉不适合这趟旅行的城市'}</p></div><strong>${p[key].length}/30</strong></div><div class="preference-selected">${p[key].map(c=>`<button data-room-action="pref-remove" data-value="${key}" data-id="${esc(c.id)}" aria-label="移除${esc(c.name)}">${esc(c.name)} ${ui.icon('x')}</button>`).join('')||'<span class="small-note">还没有添加城市</span>'}</div><label class="field"><span>添加${key==='wants'?'想去':'不想去'}的城市</span><div class="preference-city-input"><input id="pref-${key}-query" list="preference-city-list" maxlength="30" value="${esc(p.queries?.[key]||'')}" aria-label="${key==='wants'?'添加想去的城市':'添加不想去的城市'}" placeholder="搜索或填写城市，如长沙"><button class="secondary" data-room-action="pref-add" data-value="${key}">添加</button></div></label></section>`;
  ui.sheet('我的旅行偏好',`<div class="preference-page"><header class="preference-pass"><div><span>下一站 · 我的旅行名片</span><h3>${esc(me?.name||'我')}，你想怎么走？</h3><p>保存后伙伴能看到你的想法，只有你可以修改。</p></div><span class="preference-pass-stamp" aria-hidden="true">${ui.icon('navigation')}</span></header><div class="preference-essentials"><section class="pref-budget-card"><div class="pref-section-heading"><span>${ui.icon('wallet')}</span><div><h3>这趟旅行的预算</h3><p>包含往返交通、住宿和当地花费。</p></div></div><label class="field"><span>人均预算上限（元）</span><input id="pref-budget" type="number" min="1" max="100000" step="1" inputmode="numeric" placeholder="未确定可留空" value="${esc(p.budget)}"></label></section><section class="pref-days-card"><div class="pref-section-heading"><span>${ui.icon('calendar-days')}</span><div><h3>想玩多久</h3><p>选一个范围，也可以手动调整。</p></div></div><div class="fields-two"><label class="field"><span>最少天数</span><input id="pref-days-min" type="number" min="1" max="14" inputmode="numeric" placeholder="如 3" value="${esc(p.min)}"></label><label class="field"><span>最多天数</span><input id="pref-days-max" type="number" min="1" max="14" inputmode="numeric" placeholder="如 5" value="${esc(p.max)}"></label></div><div class="choice-row">${[[2,3],[3,5],[5,7],[7,14]].map(([a,b])=>`<button class="choice" data-room-action="pref-range" data-value="${a},${b}">${a}–${b} 天</button>`).join('')}</div></section></div><div class="preference-city-grid">${citySection('wants')}${citySection('dislikes')}</div><datalist id="preference-city-list">${ui.cities().map(c=>`<option value="${esc(c.name)}">${esc(c.province||'')}</option>`).join('')}</datalist><p class="preference-save-note">想去的城市会同步到你的伙伴卡片和房间候选。输入框中未点“添加”的城市，保存时也会一并加入。</p><p id="room-error" class="form-error" role="alert"></p></div>`, '<button class="secondary" data-action="close">取消</button><button class="primary" data-room-action="save-preferences">保存并同步偏好</button>');
  $('#sheet').classList.add('preference-sheet');
 }

 function candidateSection(r){return `<section class="room-section room-candidates"><div class="room-candidates-head"><div><span class="room-candidates-kicker">NEXT STOP / CITY PICKS</span><div class="room-section-heading"><h2>一起选下一站</h2><span>${r.candidates.length} 座候选城市</span></div></div>${!r.closed?'<div class="room-tools"><button class="primary" data-room-action="dart">扔个飞镖</button><button class="secondary" data-room-action="add">推荐一个城市</button><button class="text-button" data-room-action="import">从我的候选里选 ↗</button></div>':''}</div><div class="room-city-grid">${r.candidates.map((c,i)=>cityCard(c,r,i)).join('')}</div>${!r.candidates.length?'<p class="room-empty">先填写想去的城市，大家的推荐会出现在这里。</p>':''}</section>`}
 function candidatesPage(){dirty=false;if(!current)return `<section class="page-intro"><h1>大家的候选</h1><p>选择一个旅行房间，看看伙伴们想去哪。</p></section><div class="page-content"><button class="primary" data-room-action="hub">选择旅行房间</button></div>`;return `<section class="page-intro shared-candidates-intro"><h1>大家的候选</h1><div class="shared-candidates-room"><p>${esc(current.title)} · ${current.members.length} 位同行伙伴</p><button class="text-button" data-room-action="hub">切换房间</button></div>${error?`<p role="alert">${esc(error)}</p>`:''}</section><div class="room-page shared-candidates-body">${candidateSection(current)}</div>`}
 function render(){
  dirty=false;
  if(!activeId){const rooms=Object.entries(saved);return `<div class="room-lobby"><section class="room-lobby-hero"><div class="room-lobby-hero-copy"><h1>一起，把下一站定下来。</h1><p>共享候选、各自投票，让每个人的想法都有位置。</p><div class="room-lobby-actions"><button class="primary" data-room-action="new">${ui.icon('plus')}创建旅行房间</button><button class="secondary" data-room-action="paste-invite">我有邀请链接</button></div></div><div class="room-lobby-visual"><img src="assets/anan-suitcase.png" alt="安安" width="260" height="260"><span>下一站，和朋友一起</span></div></section><section class="room-lobby-section" aria-label="我的房间"><div class="room-lobby-heading"><h2>我的房间</h2><span>${rooms.length} 个房间</span></div>${rooms.length?`<div class="room-lobby-grid">${rooms.map(([id,r],index)=>`<button class="room-lobby-ticket" data-room-action="open" data-id="${esc(id)}"><span class="room-lobby-ticket-copy"><span class="room-lobby-ticket-type">下一站 · 房间票</span><strong class="room-lobby-ticket-title">${esc(r.title)}</strong><span class="room-lobby-ticket-member">以「${esc(r.name||'成员')}」的身份继续</span><span class="room-lobby-ticket-enter">进入房间 ${ui.icon('arrow-up-right')}</span></span><span class="room-lobby-ticket-art" aria-hidden="true"><img src="assets/${index%2?'room-ticket-suitcase.png':'room-ticket-camera.png'}" alt=""></span><span class="room-lobby-ticket-stub" aria-hidden="true"><span class="room-lobby-ticket-stub-label">NEXT<br>STOP</span><span class="room-lobby-ticket-barcode"></span><span class="room-lobby-ticket-number">ROOM PASS</span></span></button>`).join('')}</div>`:'<div class="room-lobby-empty">还没有加入房间。创建一个，邀请朋友一起出发。</div>'}</section></div>`;}
  if(!current)return `<div class="room-page"><button class="text-button" data-room-action="hub">返回我的房间</button><h1>${error?'房间暂时没打开':'正在打开房间…'}</h1><p role="status">${esc(error||'正在获取大家的最新想法。')}</p><button class="secondary" data-room-action="refresh">重新连接</button></div>`;
  return roomWorkspace(current);
 }

 function planHTML(p,r,index=day,dayAction='day',editable=true){const c=r.candidates.find(c=>c.id===p.city),d=p.days[index],control=(kind,i)=>`<button class="${kind==='add'?'text-button':'card-pencil'}" aria-label="${kind==='add'?'添加安排':'编辑这张卡片'}" title="编辑" data-room-action="edit-plan-card" data-kind="${kind}" data-index="${i}" data-day="${index}" data-source="${dayAction==='proposal-day'?'proposal':'shared'}">${kind==='add'?'＋ 添加一个安排':ui.icon('pencil')}</button>`;return `<div class="room-plan-heading"><h3>${esc(c?.name||p.city)} · ${p.days.length} 天</h3><p>${p.date?esc(p.date)+' 出发':'日期待定'} · ${esc(p.arrival)} 抵达 / 末日 ${esc(p.departure)} 离开</p><details class="plan-overview"><summary>查看行程概览</summary><p>${esc(p.summary)}</p></details></div>${TripDetails.destinationPhoto(c?.name||p.city)}<div class="day-layout"><nav class="day-tabs room-day-tabs" aria-label="选择行程天数">${p.days.map((_,i)=>`<button class="day-tab ${i===index?'active':''}" aria-pressed="${i===index}" data-room-action="${dayAction}" data-value="${i}">第 ${i+1} 天</button>`).join('')}</nav><div class="day-content"><h3>${esc(d.title)}</h3>${TripDetails.route(d)}${TripDetails.timeline(d).map(entry=>{if(entry.kind==='meal')return TripDetails.meal(entry.meal,p,index,c?.name||p.city,false,entry.time,control('meals',entry.meal.type),{...entry,stopControl:entry.stop?`<button class="text-button meal-schedule-edit" data-room-action="edit-plan-card" data-kind="stop" data-index="${entry.index}" data-day="${index}" data-source="${dayAction==='proposal-day'?'proposal':'shared'}">修改用餐时间与费用</button>`:''});const s=entry.stop;return `<article class="room-stop"><time>${esc(s.time)}</time><div>${TripDetails.placeHeading(s.name,c?.name||p.city)}${TripDetails.placePhoto(s.name,c?.name||p.city)}${TripDetails.briefNote(s.note)}${TripDetails.transit(s,c?.name||p.city)}${entry.meal?TripDetails.meal(entry.meal,p,index,c?.name||p.city,true,s.time,control('meals',entry.meal.type)):''}<small>${s.duration} 分钟 · 预计 ¥${s.cost} / 人</small>${control('stop',entry.index)}</div></article>`}).join('')}${control('add',-1)}${TripDetails.budgetSummary(p,true,r.closed)}${TripDetails.lodging(p,c?.name||p.city,false,control)}</div></div>`}
 function cardDraftKey(e){return 'nextstop-card-draft-'+JSON.stringify([e.roomId,e.proposalId||null,e.day,e.kind,String(e.index)])}
 function storedCardDraft(edit){const target={...edit,roomId:activeId};try{const old=JSON.parse(sessionStorage.getItem('nextstop-shared-edit-'+activeId)||'null');if(old)sessionStorage.setItem(cardDraftKey(old),JSON.stringify(old));const draft=JSON.parse(sessionStorage.getItem(cardDraftKey(target))||'null');return draft&&cardDraftKey(draft)===cardDraftKey(target)?draft:null}catch{return null}}
 function rememberSharedEdit(){try{sessionStorage.setItem('nextstop-shared-edit-'+sharedEdit.roomId,JSON.stringify(sharedEdit));sessionStorage.setItem(cardDraftKey(sharedEdit),JSON.stringify(sharedEdit))}catch{}}
 function sharedEditor(edit,resume=false){
  if(current.closed){ui.toast('房间已关闭，暂时不能编辑');return}
  if(resume){try{sharedEdit=JSON.parse(sessionStorage.getItem('nextstop-shared-edit-'+activeId))}catch{}if(!sharedEdit)return}
  else{
   const pending=storedCardDraft(edit);if(pending){sharedEdit=pending;rememberSharedEdit();sharedEditor(null,true);return}
   const item=edit.proposalId?current.proposals?.[edit.proposalId]:null,p=edit.proposalId?item?.plan:current.plan,d=p?.days[edit.day];if(!p||!d)return;
   const before=edit.kind==='stop'?d.stops[edit.index]:edit.kind==='meals'?d.meals?.find(m=>m.type===edit.index):edit.kind==='add'?null:p.lodging?.[edit.kind]?.[edit.index];
   if(before===undefined)return;
   sharedEdit={...edit,returnScroll:{sheet:$('#sheet').scrollTop,content:$('#sheet-content').scrollTop},roomId:activeId,epoch:item?(item.epoch||1):(current.planEpoch||0),baseVersion:item?item.version:current.planVersion,before:before?JSON.parse(JSON.stringify(before)):null,draft:before?JSON.parse(JSON.stringify(before)):{name:'',time:'18:00',duration:60,cost:0,kind:'place',note:'',locked:false},operationId:crypto.randomUUID()};
  }
  const e=sharedEdit,v=e.draft,stop=['stop','add'].includes(e.kind);
  const fields=stop?[['name','地点或活动',60],['note','备注',400]]:e.kind==='meals'?[['area','用餐地区或餐厅',80],['suggestion','想吃什么',200],['note','用餐备注',200]]:e.kind==='areas'?[['name','住宿地区',60],['reason','选择理由',250],['transport','交通说明',200]]:[['name','酒店名称',100],['area','所在地区',60],['reason','选择理由',250]];
  ui.sheet(e.kind==='add'?'添加行程安排':e.kind==='meals'?'编辑'+({breakfast:'早餐',lunch:'午餐',dinner:'晚餐'}[e.index]||'用餐'):'编辑'+(v.name||'行程卡片'),`<p class="small-note">${esc(current.title)} · 第 ${e.day+1} 天 · 保存后直接更新旅行方案</p><p id="shared-edit-notice" class="small-note" role="status">编辑期间保留你的输入，不会被伙伴的更新打断。</p><form id="shared-card-form">${fields.map(([key,label,max])=>`<label class="field"><span>${label}${key==='name'?'':' · 选填'}</span><textarea name="${key}" maxlength="${max}" ${key==='name'?'required':''} rows="2">${esc(v[key]||'')}</textarea></label>`).join('')}${stop?`<div class="fields-two"><label class="field"><span>开始时间</span><input name="time" type="time" required value="${esc(v.time)}"></label><label class="field"><span>停留分钟</span><input name="duration" type="number" min="15" max="720" step="1" required value="${v.duration}"></label><label class="field"><span>预计花费 / 人</span><input name="cost" type="number" min="0" max="10000" required value="${v.cost}"></label><label class="field"><span>类型</span><select name="kind">${[['place','游玩'],['food','餐饮'],['rest','休息']].map(([k,t])=>`<option value="${k}" ${v.kind===k?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="field"><span><input name="locked" type="checkbox" ${v.locked?'checked':''}>保留这一站</span></label>`:''}<p id="shared-edit-error" class="form-error" role="alert"></p></form><p class="small-note">不同卡片的修改会合并；同一卡片被别人改过时会提示冲突。更新后大家需重新投票。</p>`,`<button class="primary" data-room-action="save-shared-card">保存</button>${e.kind==='stop'?'<button class="secondary" data-room-action="delete-shared-card">删除这一站</button>':''}<button class="text-button" data-room-action="discard-shared-card">放弃本次编辑</button>`);
  const back=$('#sheet .close-btn');back.removeAttribute('data-action');back.dataset.roomAction='back-to-plan';back.setAttribute('aria-label','返回方案');
  $('#shared-card-form').addEventListener('input',captureSharedEdit);rememberSharedEdit();
 }
 function returnToEditedPlan(edit){if(!edit||activeId!==edit.roomId){ui.close();redraw();return}proposalMember=edit.proposalId||null;proposalDay=edit.day;proposalSheet();requestAnimationFrame(()=>{const dialog=$('#sheet'),content=$('#sheet-content');if(!dialog.open)return;dialog.scrollTop=edit.returnScroll?.sheet||0;content.scrollTop=edit.returnScroll?.content||0;});}
 function captureSharedEdit(){if(!sharedEdit)return;const form=$('#shared-card-form');if(!form)return;for(const input of form.querySelectorAll('[name]'))sharedEdit.draft[input.name]=input.type==='checkbox'?input.checked:['duration','cost'].includes(input.name)?Number(input.value):input.value;sharedEdit.operationId=crypto.randomUUID();rememberSharedEdit()}
 async function saveSharedCard(remove,button){
  if(!sharedEdit||busy)return;const e=sharedEdit,form=$('#shared-card-form');if(!remove&&!form.reportValidity())return;
  // Keep the operation ID stable across uncertain retries; typing creates a fresh ID.
  const value=remove?null:JSON.parse(JSON.stringify(e.draft));
  if(value){for(const k of Object.keys(value))if(typeof value[k]==='string')value[k]=value[k].trim();if(e.kind==='stop'&&value.name!==e.before.name)delete value.transit;}
  if(remove&&e.before?.locked){$('#shared-edit-error').textContent='请先取消保留并保存，再删除这一站。';return}
  busy=true;button.disabled=true;button.textContent='正在保存到旅行方案…';const controls=[...form.querySelectorAll('input,textarea,select'),$('#sheet .close-btn')].filter(Boolean);controls.forEach(x=>x.disabled=true);
  try{
   const data=await api('/'+e.roomId+'/actions',{type:'edit-plan',proposalId:e.proposalId||null,kind:e.kind,day:e.day,epoch:e.epoch,baseVersion:e.baseVersion,before:e.before,value,operationId:e.operationId+(remove?'-delete':'')},saved[e.roomId].token);
   accept(data,e.roomId);sessionStorage.removeItem('nextstop-shared-edit-'+e.roomId);sessionStorage.removeItem(cardDraftKey(e));sharedEdit=null;redraw();returnToEditedPlan(e);ui.toast('已保存，可以继续修改；伙伴会自动收到更新');
  }catch(err){$('#shared-edit-error').textContent=err.message;button.disabled=false;button.textContent=remove?'重试删除':'重试保存';if(err.status===409&&!$('#refresh-edit-room')){const b=document.createElement('button');b.id='refresh-edit-room';b.className='text-button';b.dataset.roomAction='refresh-edit-room';b.textContent='读取房间最新内容（保留我的输入）';$('#shared-edit-error').after(b)}}finally{controls.forEach(x=>x.disabled=false);busy=false}
 }
 function voteButtons(id,version,opinions,r=current){return `<div class="plan-vote-actions" aria-label="我的方案意见">${[['later','不满意'],['agree','确认']].map(([v,t])=>`<button class="${opinions?.[r.me]===v?'selected':''}" aria-pressed="${opinions?.[r.me]===v}" data-room-action="plan-vote" data-id="${id}" data-version="${version}" data-value="${v}" ${r.closed?'disabled':''}>${v==='agree'&&opinions?.[r.me]===v?'已确认':t} · ${Object.values(opinions||{}).filter(x=>x===v).length}</button>`).join('')}</div>`}
 function roomPhoto(name,cls){const image=typeof window!=='undefined'&&window.CITY_HIGHLIGHTS?.[String(name||'').replace(/市$/,'')]?.items?.[0]?.src;return image?`<img class="${cls}" src="${esc(image)}" alt="${esc(name)}城市风景" loading="lazy">`:`<div class="${cls} room-photo-empty">${ui.icon('map-pin')}<span>${esc(name||'目的地待定')}</span></div>`}
 function planHighlights(p){
  const days=p.days.map(d=>(d.stops||[]).filter(s=>s.kind==='place'&&s.name?.trim())),names=[];
  for(let i=0;i<8&&names.length<4;i++)for(const stops of days){const name=stops[i]?.name.trim();if(name&&!names.includes(name))names.push(name);if(names.length===4)break;}
  return `<div class="proposal-highlights" aria-label="主要景点"><span class="proposal-highlights-caption">沿途看点</span>${names.length?names.map(n=>`<span>${esc(n)}</span>`).join(''):'<span>主要景点待添加</span>'}</div>`;
}
function proposalList(r){
  const card=(p,c,author,id,version,opinions={})=>`<article class="room-plan-card ${opinions[r.me]==='later'?'plan-later':''}"><div class="proposal-cover">${roomPhoto(c.name,'proposal-photo')}<button class="proposal-cover-open" data-room-action="${id?'view-proposal':'view-plan'}" data-id="${id}" aria-label="查看${esc(c.name)}旅行方案"></button><div class="proposal-card-header"><span class="proposal-author"><span class="member-initial">${esc(Array.from(author)[0]||'旅')}</span>${esc(author)} 的方案</span></div><span class="proposal-trip-sticker" aria-label="第 ${version} 版，${p.days.length} 天"><small>第 ${version} 版</small><strong>${String(p.days.length).padStart(2,'0')}</strong><em>DAYS</em></span><div class="proposal-cover-title"><h3>${esc(c.name)}</h3><span>${p.days.length} 天</span></div></div><div class="proposal-card-body"><p class="proposal-date">${p.date?esc(p.date)+' 出发':'日期待定'}</p>${planHighlights(p)}<div class="proposal-card-links"><button class="room-plan-link" data-room-action="${id?'view-proposal':'view-plan'}" data-id="${id}">查看方案 ${ui.icon('arrow-up-right')}</button>${!r.closed?`<button class="proposal-edit-entry" data-room-action="collaborate-proposal" data-id="${id}" aria-label="共同编辑${esc(c.name)}行程">共同编辑</button>`:''}</div></div><div class="proposal-card-footer">${voteButtons(id,version,opinions,r)}</div>${!r.closed&&(r.me===r.owner||id===r.me)?`<button class="text-button proposal-delete" data-room-action="delete-proposal" data-id="${id}" data-version="${version}" aria-label="删除${esc(c.name)}方案">删除方案</button>`:''}</article>`;
  return `<div class="room-plan-grid">${r.plan?card(r.plan,r.candidates.find(c=>c.id===r.plan.city)||{name:ui.cities?.().find(c=>c.id===r.plan.city)?.name||r.plan.city},r.members.find(m=>m.id===r.owner)?.name||'伙伴','',r.planVersion,r.planOpinions):''}${Object.entries(r.proposals||{}).map(([id,x])=>card(x.plan,x.city,r.members.find(m=>m.id===id)?.name||'伙伴',id,x.version,x.opinions)).join('')}</div>`;
 }

 function selectedPlan(){const item=proposalMember?current.proposals?.[proposalMember]:null;return item?{plan:item.plan,version:item.version,proposalId:proposalMember}:current.plan?{plan:current.plan,version:current.planVersion,proposalId:null}:null}
 let loadedHistory=[];
 async function roomHistory(){const selected=selectedPlan();if(!selected)return;ui.sheet('方案历史版本','<p role="status">正在读取历史版本…</p>');try{loadedHistory=(await api('/'+activeId+'/history',null,saved[activeId].token)).entries;const entries=loadedHistory.filter(x=>x.proposalId===selected.proposalId);ui.sheet('方案历史版本',entries.length?`<p>恢复旧版会同步给伙伴，并生成新的房间版本；实际花费保持不变。</p><div class="history-list">${entries.map(x=>`<button class="history-row" data-room-action="view-history" data-id="${esc(x.id)}"><span><strong>第 ${x.version} 版</strong><small>${esc(x.at.slice(0,16).replace('T',' '))} · ${x.plan.days.length} 天</small></span>${ui.icon('chevron-right')}</button>`).join('')}</div>`:'<p>还没有历史版本。之后的行程修改会保留最近 8 版。</p>','<button class="secondary" data-room-action="back-to-proposal">返回方案</button>')}catch(e){ui.sheet('历史版本暂不可用',`<p role="alert">${esc(e.message)}</p>`,'<button class="secondary" data-room-action="back-to-proposal">返回方案</button>')}}
 function roomHistoryDetail(id){const selected=selectedPlan(),entry=loadedHistory.find(x=>x.id===id&&x.proposalId===selected?.proposalId);if(!entry)return;ui.sheet('恢复第 '+entry.version+' 版？',`<p>当前方案与旧版的主要差异：</p><ul class="history-diff">${TripPlanFeatures.diff(selected.plan,entry.plan)}</ul><p class="small-note">恢复后伙伴会看到新版本，原有确认需重新选择。</p><p id="room-error" class="form-error" role="alert"></p>`,`<button class="secondary" data-room-action="history">返回历史</button><button class="primary" data-room-action="restore-history" data-id="${esc(id)}" data-version="${selected.version}">恢复这一版</button>`)}
 let expenseSnapshot=null;
 function roomExpenseEditor(id=''){const selected=selectedPlan();if(!selected||current.closed)return;const x=TripPlanFeatures.expenses(selected.plan).find(x=>x.id===id);expenseSnapshot={proposalId:selected.proposalId,before:x?JSON.parse(JSON.stringify(x)):null};ui.sheet(x?'编辑实际花费':'记一笔实际花费',TripPlanFeatures.expenseForm(x,selected.plan.days.length,current.members.length,true,current.title),`<p class="expense-footer-note">保存后，房间里的伙伴都能看到。</p><button class="secondary" data-room-action="back-to-proposal">返回方案</button><button class="primary" data-room-action="save-expense" data-id="${esc(id)}">保存这笔花费</button>${x?`<button class="text-button" data-room-action="delete-expense" data-id="${esc(id)}">删除这笔</button>`:''}`);
  const form=$('#room-expense-form'),ids=x?.participantIds||current.members.map(m=>m.id),former=[...new Set([...(x?.participantIds||[]),...(x?.payerId?[x.payerId]:[])])].filter(id=>!current.members.some(m=>m.id===id)),members=[...current.members,...former.map(id=>({id,name:(current.memberNames?.[id]||'已退出的伙伴')+'（已退出）'}))];
  form.querySelector('.expense-split-fields').insertAdjacentHTML('afterend',`<label class="expense-field"><span>谁先付的钱</span><select name="payerId" required><option value="">请选择付款人</option>${members.map(m=>`<option value="${esc(m.id)}" ${x?.payerId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><fieldset class="expense-participants"><legend>这笔费用由谁分摊</legend>${members.map(m=>`<label><input type="checkbox" name="participantIds" value="${esc(m.id)}" ${ids.includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}</fieldset>`);
  form.elements.splitCount.readOnly=true;form.querySelectorAll('[data-expense-step]').forEach(b=>b.disabled=true);form.querySelector('.expense-help').textContent='勾选实际参与的伙伴，人数和人均金额会自动更新。';form.querySelector('.expense-ticket-bottom').textContent='人均显示四舍五入值；结算按分分配余数，总额保持不变。';
  if(x&&!x.payerId){const note=document.createElement('p');note.className='info-note';note.textContent=x.totalAmount==null?'这笔旧记录只保存了人均 ¥'+x.amount+'，请补填实际总金额，并确认付款人和分摊伙伴。':'这笔旧记录原来按 '+x.splitCount+' 人分摊，请确认下面实际参与的伙伴。';form.querySelector('.expense-flow').prepend(note);if(x.totalAmount==null)form.elements.totalAmount.value='';}
  const update=()=>{form.elements.splitCount.value=String(form.querySelectorAll('[name=participantIds]:checked').length);TripPlanFeatures.updateExpensePreview(form)};form.addEventListener('change',update);update();
 }
 function roomEstimateEditor(){const selected=selectedPlan();if(!selected||current.closed)return;ui.sheet('住宿与交通预估',TripPlanFeatures.estimateForm(selected.plan.manualEstimate),'<button class="primary" data-room-action="save-estimate">保存并同步</button><button class="secondary" data-room-action="back-to-proposal">返回方案</button>')}
 async function saveRoomEstimate(){const selected=selectedPlan(),form=$('#estimate-form');if(!selected||!form||!form.reportValidity())return;let value;try{value=TripPlanFeatures.readEstimate(form)}catch(e){form.querySelector('#estimate-error').textContent=e.message;return}const before=TripPlanFeatures.manualEstimate(selected.plan.manualEstimate);if(await mutate({type:'set-estimate',proposalId:selected.proposalId,before,value})){proposalSheet();ui.toast('预估费用已同步给伙伴')}}
 async function saveRoomExpense(id,remove=false){const selected=selectedPlan(),form=$('#room-expense-form');if(!selected||!form||(!remove&&!form.reportValidity()))return;const before=expenseSnapshot?.before||null;let value=null;if(!remove)try{value=TripPlanFeatures.readExpense(form,id);value.payerId=form.elements.payerId.value;value.participantIds=[...form.querySelectorAll('[name=participantIds]:checked')].map(x=>x.value).sort();if(!value.payerId||!value.participantIds.length)throw Error('请选择付款人，并至少勾选一位分摊伙伴。')}catch(e){$('#room-error').textContent=e.message;return}if(await mutate({type:'set-expense',proposalId:expenseSnapshot.proposalId,id:id||value.id,before,value})){roomTools.ledger(expenseSnapshot.proposalId||'shared');ui.toast(remove?'花费已删除并同步':'实际花费已同步，结算已更新')}}
 function roomTripDate(start,index){const date=new Date(start+'T00:00:00Z');if(!Number.isFinite(date.getTime()))return start;date.setUTCDate(date.getUTCDate()+index);return date.toISOString().slice(0,10)}
 function folderPlanHTML(p,r,index,dayAction,author){
  const c=r.candidates.find(candidate=>candidate.id===p.city),city=c?.name||p.city,d=p.days[index],source=dayAction==='proposal-day'?'proposal':'shared';
  const control=(kind,i)=>`<button class="${kind==='add'?'text-button':'card-pencil'}" aria-label="${kind==='add'?'添加安排':'编辑这张卡片'}" title="编辑" data-room-action="edit-plan-card" data-kind="${kind}" data-index="${i}" data-day="${index}" data-source="${source}">${kind==='add'?'＋ 添加一个安排':ui.icon('pencil')}</button>`;
  const photo=window.CITY_HIGHLIGHTS?.[String(city).replace(/市$/,'')]?.items?.[0],photoOK=photo&&/^assets\/[a-zA-Z0-9_./-]+$/.test(photo.src),photoSrc=photoOK?esc(photo.src):'',photoCredit=photoOK?esc(photo.author||'目的地影像'):'';
  const entries=TripDetails.timeline(d),photoAt=Math.min(3,d.stops.length-1),dateText=p.date?esc(p.date)+' 出发':'日期待定';
  let stopNumber=0;
  const rows=entries.map(entry=>{
   if(entry.kind==='meal')return `<div class="journal-entry journal-entry-meal"><div class="journal-entry-time"><span>${entry.time?esc(entry.time):'待安排'}</span></div><div class="journal-ticket">${TripDetails.meal(entry.meal,p,index,city,false,entry.time,control('meals',entry.meal.type),{...entry,stopControl:entry.stop?`<button class="text-button meal-schedule-edit" data-room-action="edit-plan-card" data-kind="stop" data-index="${entry.index}" data-day="${index}" data-source="${source}">修改用餐时间与费用</button>`:''})}</div></div>`;
   const s=entry.stop,number=++stopNumber,withPhoto=photoOK&&number-1===photoAt;
   return `<article class="journal-entry ${withPhoto?'journal-entry-photo':''}"><div class="journal-entry-time"><time datetime="${esc(s.time)}">${esc(s.time)}</time><small>${String(number).padStart(2,'0')}</small></div><div class="journal-ticket"><span class="journal-kind" aria-hidden="true">${ui.icon(s.kind==='food'?'utensils':s.kind==='rest'?'coffee':'map-pin')}</span><div class="journal-ticket-copy">${TripDetails.placeHeading(s.name,city)}${TripDetails.briefNote(s.note)}${TripDetails.transit(s,city)}${entry.meal?TripDetails.meal(entry.meal,p,index,city,true,s.time,control('meals',entry.meal.type)):''}</div>${withPhoto?`<figure class="journal-stuck-photo"><img src="${photoSrc}" alt="${esc(city)}目的地影像参考" loading="lazy" onerror="this.closest('figure').hidden=true"><figcaption>城市影像 · ${photoCredit}</figcaption></figure>`:''}<div class="journal-ticket-meta"><span>${Number(s.duration)||0} 分钟 · 预计 ¥${Number(s.cost)||0} / 人</span>${control('stop',entry.index)}</div></div></article>`;
  }).join('');
  return `<section class="journal-cover"><button class="journal-back" data-action="close">${ui.icon('arrow-left')}返回旅行房间</button><div class="journal-cover-copy"><h3>${esc(city)} <span>·</span> ${p.days.length} 天行程</h3><p>${esc(author)} 的旅行方案</p><div class="journal-cover-meta"><span><b>去程</b>${dateText} · ${esc(p.arrival)} 抵达</span><span><b>返程</b>${esc(p.date?roomTripDate(p.date,p.days.length-1):'日期待定')} · ${esc(p.departure)} 离开</span></div></div>${photoOK?`<figure class="journal-cover-photo"><img src="${photoSrc}" alt="${esc(city)}目的地影像" onerror="this.closest('figure').hidden=true"><figcaption>${esc(city)} / TRAVEL JOURNAL</figcaption></figure>`:`<div class="journal-cover-placeholder">${esc(city)}</div>`}</section><div class="journal-folder-layers" aria-hidden="true"></div><div class="day-layout journal-layout"><nav class="day-tabs room-day-tabs" aria-label="选择行程天数">${p.days.map((_,i)=>`<button class="day-tab ${i===index?'active':''}" aria-pressed="${i===index}" data-room-action="${dayAction}" data-value="${i}">第 ${i+1} 天</button>`).join('')}</nav><div class="day-content journal-day"><header class="journal-day-head"><span class="journal-day-stamp"><small>DAY</small><strong>${String(index+1).padStart(2,'0')}</strong></span><div><h3>${esc(d.title)}</h3>${p.date?`<p>${esc(roomTripDate(p.date,index))} · 第 ${index+1} 天</p>`:''}</div></header>${TripDetails.route(d)}<div class="journal-order-head"><strong>按时间出发</strong><span>从上到下就是当天的游玩顺序</span></div><div class="journal-timeline">${rows||'<p class="journal-empty">这一天还没有安排，可以添加第一站。</p>'}</div><div class="journal-add">${control('add',-1)}</div><details class="journal-overview"><summary>查看行程概览</summary><p>${esc(p.summary)}</p></details><div class="journal-extras">${TripDetails.budgetSummary(p,true,r.closed)}${TripDetails.lodging(p,city,false,control)}</div></div></div>`;
 }
 function proposalSheet(){const item=proposalMember?current.proposals?.[proposalMember]:current.plan?{plan:current.plan,city:current.candidates.find(c=>c.id===current.plan.city)||{name:current.plan.city},version:current.planVersion,opinions:current.planOpinions}:null;if(!item){ui.toast('这份方案已撤回，请刷新房间');return}proposalDay=Math.min(proposalDay,item.plan.days.length-1);const name=current.members.find(m=>m.id===(proposalMember||current.owner))?.name||'伙伴';ui.sheet(name+'的'+item.city.name+'行程',folderPlanHTML(item.plan,{...current,candidates:[item.city]},proposalDay,proposalMember?'proposal-day':'legacy-day',name)+`<p class="small-note">点卡片右上角的铅笔共同修改，保存后伙伴会收到更新。内容更新后需重新投票。</p>`,`<button class="secondary" data-action="close">返回房间</button><button class="secondary" data-room-action="history">历史版本</button>${voteButtons(proposalMember||'',item.version,item.opinions)}`);$('#sheet').classList.add('itinerary-sheet')}
 function editRoomDraft(source,edit){const proposal=source==='proposal',item=proposal?current.proposals?.[proposalMember]:null,p=proposal?item?.plan:current.plan;if(!p)return;const c=proposal?item.city:current.candidates.find(c=>c.id===p.city);ui.editPlan(p,c,{roomId:activeId,role:isOwner()?'owner':'member',baseVersion:isOwner()?current.planVersion:current.proposals?.[current.me]?.version||0,...((!proposal&&isOwner())||(proposal&&proposalMember===current.me)?{syncedFingerprint:fingerprint(p)}:{}),...(edit?{edit}:{})})}
